sources.BRPB01Batch:
public class BRPB01Batch implements Database.Batchable<Object> {
    public Iterable<Object> start(Database.BatchableContext context) {
        return new List<Object>{ 'a', 'b', 'c' };
    }

    public void execute(Database.BatchableContext context, Iterable<Object> scope) {
        Integer count = 0;
        for (Object item : scope) {
            count++;
        }
        Object raw = scope;
        insert new Account(Name = 'PB01|' + count + '|' + (raw instanceof List<Object>));
    }

    public void finish(Database.BatchableContext context) {
    }
}

sources.BRPB01Test:
@IsTest
private class BRPB01Test {
    @IsTest
    static void observe() {
        String observed;
        try {
            Test.startTest();
            Database.executeBatch(new BRPB01Batch());
            Test.stopTest();
            List<String> names = new List<String>();
            for (Account a : [SELECT Name FROM Account WHERE Name LIKE 'PB01|%' ORDER BY Name]) {
                names.add(a.Name);
            }
            observed = String.join(names, ',');
        } catch (Exception e) {
            observed = 'EXC|' + e.getTypeName() + '|' + e.getMessage();
        }
        System.assert(false, 'P|PB01|' + observed);
    }
}

