sources.BRH1K1PCBatch:
public class BRH1K1PCBatch implements Database.Batchable<Object> {
    public Iterable<Object> start(Database.BatchableContext context) {
        return new List<Object>{ 'a', 'b', 'c' };
    }

    public void execute(Database.BatchableContext context, Iterable<Object> scope) {
        Integer count = 0;
        String kind = '';
        for (Object item : scope) {
            Object element = item;
            count++;
            kind = (element instanceof Account) ? 'Account' : ((element instanceof SObject) ? 'SObject' : ((element instanceof String) ? 'String' : 'Other'));
        }
        Object raw = scope;
        insert new Account(Name = 'H1K1PC|' + count + '|' + kind + '|' + (raw instanceof List<Object>) + '|' + (raw instanceof List<SObject>));
    }

    public void finish(Database.BatchableContext context) {
    }
}

