sources.BRH1K1ABatch:
public class BRH1K1ABatch implements Database.Batchable<Account> {
    public Database.QueryLocator start(Database.BatchableContext context) {
        return Database.getQueryLocator([SELECT Id, Name FROM Account WHERE Name LIKE 'seed-H1K1A-%']);
    }

    public void execute(Database.BatchableContext context, Iterable<Account> scope) {
        Integer count = 0;
        String kind = '';
        for (Account item : scope) {
            Object element = item;
            count++;
            kind = (element instanceof Account) ? 'Account' : ((element instanceof SObject) ? 'SObject' : ((element instanceof String) ? 'String' : 'Other'));
        }
        Object raw = scope;
        insert new Account(Name = 'H1K1A|' + count + '|' + kind + '|' + (raw instanceof List<Object>) + '|' + (raw instanceof List<SObject>));
    }

    public void finish(Database.BatchableContext context) {
    }
}

