private class BRH1K1ATest {
    @IsTest
    static void observe() {
        String observed;
        try {
            List<Account> seeds = new List<Account>();
            for (Integer i = 0; i < 3; i++) {
                seeds.add(new Account(Name = 'seed-H1K1A-' + i));
            }
            insert seeds;
            Test.startTest();
            Database.executeBatch(new BRH1K1ABatch());
            Test.stopTest();
            List<String> names = new List<String>();
            for (Account a : [SELECT Name FROM Account WHERE Name LIKE 'H1K1A|%' ORDER BY Name]) {
                names.add(a.Name);
            }
            observed = String.join(names, ',');
        } catch (Exception e) {
            observed = 'EXC|' + e.getTypeName() + '|' + e.getMessage();
        }
        System.assert(false, 'P|H1K1A|' + observed);
    }
}

sources.BRH1K1ACBatch:
public class BRH1K1ACBatch implements Database.Batchable<Account> {
    public Database.QueryLocator start(Database.BatchableContext context) {
        return Database.getQueryLocator([SELECT Id, Name FROM Account WHERE Name LIKE 'seed-H1K1AC-%']);
    }

    public void execute(Database.BatchableContext context, List<Account> scope) {
        Integer count = 0;
        String kind = '';
        for (Account item : scope) {
            Object element = item;
            count++;
            kind = (element instanceof Account) ? 'Account' : ((element instanceof SObject) ? 'SObject' : ((element instanceof String) ? 'String' : 'Other'));
        }
        Object raw = scope;
        insert new Account(Name = 'H1K1AC|' + count + '|' + kind + '|' + (raw instanceof List<Object>) + '|' + (raw instanceof List<SObject>));
    }

    public void finish(Database.BatchableContext context) {
    }
}

